def transform(grid):
    from collections import deque

    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find zero cells connected to the edge by 4-way paths.
    exterior = [[False] * w for _ in range(h)]
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and not exterior[r][c]:
                exterior[r][c] = True
                q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and not exterior[r][c]:
                exterior[r][c] = True
                q.append((r, c))

    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                    and not exterior[nr][nc]):
                exterior[nr][nc] = True
                q.append((nr, nc))

    # Enclosed zero cells next to a contour become 3.
    enclosed_boundary = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 and not exterior[r][c]:
                near_one = False
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1:
                            near_one = True
                            enclosed_boundary.add((nr, nc))
                if near_one:
                    out[r][c] = 3

    # Add a 2 halo outside the contour components that border an enclosure.
    marked = set(enclosed_boundary)
    q = deque(enclosed_boundary)
    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1
                    and (nr, nc) not in marked):
                marked.add((nr, nc))
                q.append((nr, nc))

    for r, c in marked:
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                nr, nc = r + dr, c + dc
                if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                        and exterior[nr][nc]):
                    out[nr][nc] = 2

    return out
